begin;
create table if not exists public.quiz_admins(user_id uuid primary key references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.quiz_admin_emails(email_hash text primary key);
alter table public.quiz_admin_emails enable row level security;
revoke all on public.quiz_admin_emails from public,anon,authenticated;
create table if not exists public.admin_quizzes(id uuid primary key default gen_random_uuid(),template_key text not null unique,draft jsonb not null,revision integer not null default 1,published_revision integer,updated_at timestamptz not null default now());
alter table public.quiz_admins enable row level security;
alter table public.admin_quizzes enable row level security;
revoke all on public.quiz_admins,public.admin_quizzes from anon,authenticated;
alter table public.quiz_templates add column if not exists enabled boolean not null default true;
alter table public.quiz_templates add column if not exists sale_price numeric(12,2) not null default 0;
alter table public.quiz_templates add column if not exists public_metadata jsonb not null default '{}';
alter table public.quiz_templates add column if not exists managed boolean not null default false;
alter table public.questions add column if not exists definition jsonb not null default '{}';
alter table public.rooms add column if not exists admin_document jsonb;
alter table public.answers add column if not exists response jsonb;
alter table public.answers add column if not exists needs_review boolean not null default false;

create or replace function public.is_quiz_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.quiz_admins where user_id=auth.uid()) or exists(select 1 from auth.users u join public.quiz_admin_emails a on a.email_hash=encode(extensions.digest(lower(u.email),'sha256'),'hex') where u.id=auth.uid() and u.email_confirmed_at is not null)$$;
revoke all on function public.is_quiz_admin() from public;
grant execute on function public.is_quiz_admin() to anon,authenticated;

create or replace function public.validate_quiz_document(doc jsonb) returns void language plpgsql set search_path='' as $$
declare r jsonb; q jsonb; o jsonb; k text; n integer:=0; v numeric; selected integer; opts integer;
begin
 if jsonb_typeof(doc) is distinct from 'object' or length(btrim(coalesce(doc->>'title',''))) not between 1 and 100 then raise exception 'Укажите название квиза (до 100 символов)'; end if;
 if doc->'cover' is not null and doc->'cover'<>'null'::jsonb then
  if jsonb_typeof(doc->'cover') is distinct from 'object' or coalesce(doc->'cover'->>'type','')<>'image' or coalesce(doc->'cover'->>'url','') !~ '^https://[^[:space:]]+$' or length(doc->'cover'->>'url')>2000 or length(coalesce(doc->'cover'->>'alt',''))>200 then raise exception 'Обложка: укажите HTTPS-ссылку на изображение и описание до 200 символов'; end if;
 end if;
 if length(coalesce(doc->>'description',''))>500 or length(coalesce(doc->>'category',''))>60 then raise exception 'Слишком длинное описание или тема'; end if;
 if coalesce(doc->>'price','') !~ '^[0-9]{1,8}(\.[0-9]{1,2})?$' then raise exception 'Цена: от 0 до 99999999,99 ₽'; end if;
 if coalesce(doc->>'score_timing','') not in ('question','round','quiz') or coalesce(doc->>'reveal_timing','') not in ('question','round','quiz') then raise exception 'Выберите порядок баллов и раскрытия ответов'; end if;
 if jsonb_typeof(doc->'rounds') is distinct from 'array' then raise exception 'Добавьте тур'; end if;
 if jsonb_array_length(doc->'rounds') not between 1 and 20 then raise exception 'От 1 до 20 туров'; end if;
 for r in select value from jsonb_array_elements(doc->'rounds') loop
  if length(btrim(coalesce(r->>'title',''))) not between 1 and 100 then raise exception 'Укажите название тура'; end if;
  if jsonb_typeof(r->'questions') is distinct from 'array' then raise exception 'Добавьте вопросы тура'; end if;
  if jsonb_array_length(r->'questions')=0 then raise exception 'Пустой тур нельзя публиковать'; end if;
  for q in select value from jsonb_array_elements(r->'questions') loop
   n:=n+1;k:=q->>'kind';
   if k is null or k not in ('single','multiple','text','manual') then raise exception 'Неизвестный тип ответа'; end if;
   if length(btrim(coalesce(q->>'text',''))) not between 1 and 500 then raise exception 'Вопрос: от 1 до 500 символов'; end if;
   if coalesce(q->>'points','') !~ '^[0-9]{1,5}(\.[0-9]{1,2})?$' or coalesce(q->>'duration','') !~ '^[0-9]{1,3}$' then raise exception 'Укажите баллы и время'; end if;
   if (q->>'points')::numeric not between 0 and 10000 or (q->>'duration')::integer not between 5 and 300 then raise exception 'Баллы: 0–10000; время: 5–300 секунд'; end if;
   if length(coalesce(q->>'explanation',''))>2000 then raise exception 'Пояснение: до 2000 символов'; end if;
   if k in ('single','multiple') then
    if jsonb_typeof(q->'options') is distinct from 'array' or jsonb_typeof(q->'correct') is distinct from 'array' then raise exception 'Добавьте варианты и правильные ответы'; end if;
    opts:=jsonb_array_length(q->'options');
    if opts not between 2 and 8 then raise exception 'От 2 до 8 вариантов'; end if;
    for o in select value from jsonb_array_elements(q->'options') loop
     if jsonb_typeof(o) is distinct from 'string' or length(btrim(o#>>'{}')) not between 1 and 200 then raise exception 'Вариант ответа: от 1 до 200 символов'; end if;
    end loop;
    if (select count(distinct lower(btrim(value))) from jsonb_array_elements_text(q->'options'))<>opts then raise exception 'Варианты не должны повторяться'; end if;
    if jsonb_array_length(q->'correct')=0 or (k='single' and jsonb_array_length(q->'correct')<>1) then raise exception 'Отметьте правильные варианты'; end if;
    if (select count(distinct value) from jsonb_array_elements(q->'correct'))<>jsonb_array_length(q->'correct') then raise exception 'Правильные варианты повторяются'; end if;
    for o in select value from jsonb_array_elements(q->'correct') loop
     if o::text !~ '^[0-7]$' then raise exception 'Неверный номер ответа'; end if;
     if o::text::integer>=opts then raise exception 'Номер ответа вне списка'; end if;
    end loop;
   elsif k='text' then
    if jsonb_typeof(q->'accepted') is distinct from 'array' then raise exception 'Добавьте допустимые написания ответа'; end if;
    if jsonb_array_length(q->'accepted') not between 1 and 30 then raise exception 'От 1 до 30 допустимых написаний'; end if;
    for o in select value from jsonb_array_elements(q->'accepted') loop
     if jsonb_typeof(o) is distinct from 'string' or length(btrim(o#>>'{}')) not between 1 and 500 then raise exception 'Пустой или слишком длинный допустимый ответ'; end if;
    end loop;
   end if;
   if q ? 'partial' and jsonb_typeof(q->'partial')<>'boolean' then raise exception 'Неверная настройка частичного ответа'; end if;
   if q ? 'case_sensitive' and jsonb_typeof(q->'case_sensitive')<>'boolean' then raise exception 'Неверная настройка регистра'; end if;
   foreach k in array array['media','answer_media'] loop
    if q->k is not null and q->k<>'null'::jsonb then
     if coalesce(q->k->>'type','') not in ('image','audio','video') or coalesce(q->k->>'url','') !~ '^https://[^[:space:]]+$' or length(q->k->>'url')>2000 then raise exception 'Медиа: укажите HTTPS-ссылку и тип'; end if;
    end if;
   end loop;
  end loop;
 end loop;
 if n not between 1 and 50 then raise exception 'В квизе должно быть от 1 до 50 вопросов'; end if;
end $$;
revoke all on function public.validate_quiz_document(jsonb) from public,anon,authenticated;

create or replace function public.admin_list_quizzes() returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.is_quiz_admin() then raise exception 'Доступ только администратору' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(to_jsonb(q) order by updated_at desc) from public.admin_quizzes q),'[]');end $$;
create or replace function public.admin_save_quiz(p_id uuid,p_document jsonb,p_revision integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$
declare saved public.admin_quizzes%rowtype; new_id uuid;
begin
 if not public.is_quiz_admin() then raise exception 'Доступ только администратору' using errcode='42501'; end if;
 if jsonb_typeof(p_document) is distinct from 'object' or octet_length(p_document::text)>500000 then raise exception 'Недопустимый черновик'; end if;
 if p_id is null then
  new_id:=gen_random_uuid();insert into public.admin_quizzes(id,template_key,draft) values(new_id,'admin-'||new_id::text,p_document) returning * into saved;
 else
  update public.admin_quizzes set draft=p_document,revision=revision+1,updated_at=now() where id=p_id and revision=p_revision returning * into saved;
  if not found then raise exception 'Черновик изменён в другой вкладке. Обновите список и откройте его снова' using errcode='40001'; end if;
 end if;
 return to_jsonb(saved);
end $$;
create or replace function public.admin_publish_quiz(p_id uuid,p_revision integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare saved public.admin_quizzes%rowtype; questions jsonb; timing text;
begin
 if not public.is_quiz_admin() then raise exception 'Доступ только администратору' using errcode='42501'; end if;
 select * into saved from public.admin_quizzes where id=p_id and revision=p_revision for update;
 if not found then raise exception 'Сначала сохраните актуальный черновик'; end if;
 perform public.validate_quiz_document(saved.draft);
 select jsonb_agg(q||jsonb_build_object('round',r->>'title','round_number',ri,'correct',case when q->>'kind'='single' then q->'correct'->0 else '0'::jsonb end,'answer_key',q->'correct') order by ri,qi) into questions
 from jsonb_array_elements(saved.draft->'rounds') with ordinality as rounds(r,ri) cross join lateral jsonb_array_elements(r->'questions') with ordinality as items(q,qi);
 insert into public.quiz_templates(key,title,questions,sale_price,enabled,managed,public_metadata) values(saved.template_key,saved.draft->>'title',questions,(saved.draft->>'price')::numeric,true,true,saved.draft-'rounds')
 on conflict(key) do update set title=excluded.title,questions=excluded.questions,sale_price=excluded.sale_price,enabled=true,managed=true,public_metadata=excluded.public_metadata;
 update public.admin_quizzes set published_revision=revision where id=p_id;
 return jsonb_build_object('key',saved.template_key,'published',true);
end $$;
create or replace function public.admin_unpublish_quiz(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if not public.is_quiz_admin() then raise exception 'Доступ только администратору' using errcode='42501'; end if;
 update public.quiz_templates set enabled=false where key=(select template_key from public.admin_quizzes where id=p_id);
 update public.admin_quizzes set published_revision=null where id=p_id;
end $$;
create or replace function public.list_quiz_catalog() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('key',key,'title',title,'category',coalesce(public_metadata->>'category','Общие знания'),'description',coalesce(public_metadata->>'description',''),'icon',coalesce(public_metadata->>'icon','🧩'),'level',coalesce(public_metadata->>'level','Средний'),'question_count',jsonb_array_length(questions),'price',sale_price,'currency','RUB','managed',managed,'available',sale_price=0,'cover',public_metadata->'cover') order by key),'[]') from public.quiz_templates where enabled and key<>'starter'
$$;
create or replace function public.create_quiz_room_v2(p_quiz_key text default 'starter') returns table(room_code text,host_secret uuid) language plpgsql security definer set search_path='' as $$
declare made record; t public.quiz_templates%rowtype;
begin
 select * into t from public.quiz_templates where key=p_quiz_key and enabled;
 if not found then raise exception 'Квиз недоступен. Выберите опубликованный квиз из каталога'; end if;
 if t.sale_price>0 and not public.is_quiz_admin() then raise exception 'Платный квиз: продажи пока не подключены'; end if;
 select * into made from public.create_quiz_room();
 update public.rooms set quiz_key=t.key,admin_document=case when t.managed then t.public_metadata||jsonb_build_object('questions',t.questions) else null end where code=made.room_code and host_token=made.host_secret;
 return query select made.room_code::text,made.host_secret::uuid;
end $$;
-- Rename once and close all legacy entry points. New wrappers preserve active games.
do $$ begin
 if to_regprocedure('public.quiz_game_snapshot_legacy(uuid,uuid)') is null then alter function public.quiz_game_snapshot(uuid,uuid) rename to quiz_game_snapshot_legacy; end if;
 if to_regprocedure('public.control_quiz_game_legacy(text,uuid,text,jsonb,uuid,text)') is null then alter function public.control_quiz_game_v2(text,uuid,text,jsonb,uuid,text) rename to control_quiz_game_legacy; end if;
 if to_regprocedure('public.submit_quiz_answer_legacy(uuid,uuid,uuid,integer)') is null then alter function public.submit_quiz_answer(uuid,uuid,uuid,integer) rename to submit_quiz_answer_legacy; end if;
end $$;
revoke all on function public.quiz_game_snapshot_legacy(uuid,uuid),public.control_quiz_game_legacy(text,uuid,text,jsonb,uuid,text),public.submit_quiz_answer_legacy(uuid,uuid,uuid,integer) from public,anon,authenticated;

create or replace function public.quiz_normalize_answer(v text,sensitive boolean default false) returns text language sql immutable set search_path='' as $$select case when sensitive then regexp_replace(btrim(v),'\s+',' ','g') else replace(lower(regexp_replace(btrim(v),'\s+',' ','g')),'ё','е') end$$;
revoke all on function public.quiz_normalize_answer(text,boolean) from public,anon,authenticated;

create or replace function public.quiz_game_snapshot(p_room uuid,p_player uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; r public.rooms%rowtype; q public.questions%rowtype; a public.answers%rowtype; d jsonb; reveal boolean; end_round boolean; shown text; review jsonb;
begin
 result:=public.quiz_game_snapshot_legacy(p_room,p_player);
 select * into strict r from public.rooms where id=p_room;
 -- Public hosts never receive a content editor, including old custom waiting rooms.
 result:=result||jsonb_build_object('can_edit_content',false,'locked_rules',true);
 if p_player is not null then result:=result-'can_edit_content'-'locked_rules'; end if;
 if r.admin_document is null then return result; end if;
 if r.status='waiting' then
  if p_player is null then result:=result||jsonb_build_object('quiz_title',r.admin_document->>'title','setup_questions',(select jsonb_agg(jsonb_build_object('text',v->>'text','options',coalesce(v->'options','[]'),'points',v->'points','duration',v->'duration','round',v->>'round')) from jsonb_array_elements(r.admin_document->'questions') v)); end if;
  return result;
 end if;
 select * into q from public.questions where room_id=r.id and question_number=r.current_question;d:=q.definition;
 select not exists(select 1 from public.questions where room_id=r.id and question_number=q.question_number+1 and definition->>'round_number'=d->>'round_number') into end_round;
 reveal:=r.status='finished' or (r.game_phase='reveal' and (r.admin_document->>'reveal_timing'='question' or (r.admin_document->>'reveal_timing'='round' and end_round)));
 if p_player is not null then select * into a from public.answers where question_id=q.id and player_id=p_player; end if;
 result:=result||jsonb_build_object('question',((result->'question')-'correct_option')||jsonb_build_object('kind',d->>'kind','options',coalesce(d->'options','[]'),'round',d->>'round','media',d->'media','animation',d->>'animation','round_end',end_round,'revealed',reveal,'correct_choices',case when reveal then d->'answer_key' else null end,'accepted',case when reveal then d->'accepted' else null end,'explanation',case when reveal then d->>'explanation' else null end,'answer_media',case when reveal then d->'answer_media' else null end),'my_response',a.response);
 if reveal and r.admin_document->>'reveal_timing'<>'question' then
  select jsonb_agg(jsonb_build_object('number',question_number,'text',question_text,'options',definition->'options','correct_choices',definition->'answer_key','accepted',definition->'accepted','explanation',definition->>'explanation','answer_media',definition->'answer_media') order by question_number) into review from public.questions where room_id=r.id and (r.status='finished' or definition->>'round_number'=d->>'round_number');
  result:=result||jsonb_build_object('review',review);
 end if;
 if p_player is null then
  result:=result||jsonb_build_object('pending_answers',coalesce((select jsonb_agg(jsonb_build_object('id',ans.id,'player',p.name,'response',ans.response,'max_points',qu.points,'question',qu.question_text) order by ans.answered_at) from public.answers ans join public.players p on p.id=ans.player_id join public.questions qu on qu.id=ans.question_id where qu.room_id=r.id and ans.needs_review),'[]'));
 end if;
 return result;
end $$;
revoke all on function public.quiz_game_snapshot(uuid,uuid) from public,anon,authenticated;

create or replace function public.control_quiz_game_v2(p_code text,p_host_secret uuid,p_action text,p_questions jsonb default null,p_question_id uuid default null,p_scoring_mode text default 'reveal') returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.rooms%rowtype; t public.quiz_templates%rowtype; q public.questions%rowtype; d jsonb; item jsonb; n integer:=0; opts jsonb; result jsonb; timing text; end_round boolean;
begin
 select * into r from public.rooms where code=p_code and host_token=p_host_secret for update;
 if not found then raise exception 'Нет доступа ведущего' using errcode='42501'; end if;
 if p_action='start' and r.status='waiting' then
  if r.quiz_key='custom' then raise exception 'Редактор доступен только в закрытом разделе администратора'; end if;
  select * into t from public.quiz_templates where key=r.quiz_key and enabled;
  if not found then raise exception 'Квиз снят с публикации'; end if;
  if t.managed and r.admin_document is null then update public.rooms set admin_document=t.public_metadata||jsonb_build_object('questions',t.questions) where id=r.id returning * into r; end if;
  if r.admin_document is not null then
   if not exists(select 1 from public.players where room_id=r.id) then raise exception 'Дождитесь хотя бы одного игрока'; end if;
   for d in select value from jsonb_array_elements(r.admin_document->'questions') loop
    n:=n+1; select jsonb_agg(coalesce(d->'options'->i,'"—"'::jsonb) order by i) into opts from generate_series(0,3) as slots(i);
    insert into public.questions(room_id,question_number,question_text,options,correct_option,duration,points,definition) values(r.id,n,d->>'text',opts,0,(d->>'duration')::integer,(d->>'points')::numeric,d);
   end loop;
   update public.rooms set status='playing',game_phase='question',current_question=1,question_started_at=clock_timestamp(),scoring_mode=case when r.admin_document->>'score_timing'='question' then 'reveal' else 'finish' end where id=r.id;
   return public.quiz_game_snapshot(r.id,null);
  end if;
  -- Legacy catalog rooms use canonical rules; public hosts cannot alter price/content/points.
  select jsonb_agg(jsonb_build_object('points',coalesce(v->'points','1'),'duration',coalesce(v->'duration','30')) order by ord) into opts from jsonb_array_elements(t.questions) with ordinality src(v,ord);
  return public.control_quiz_game_legacy(p_code,p_host_secret,p_action,opts,null,'reveal');
 end if;
 if r.admin_document is null then return public.control_quiz_game_legacy(p_code,p_host_secret,p_action,p_questions,p_question_id,p_scoring_mode); end if;
 if p_action='start' then return public.quiz_game_snapshot(r.id,null); end if;
 select * into q from public.questions where room_id=r.id and question_number=r.current_question;
 if p_question_id is distinct from q.id then return public.quiz_game_snapshot(r.id,null); end if;
 if p_action in ('next','finish') and exists(select 1 from public.answers a join public.questions qu on qu.id=a.question_id where qu.room_id=r.id and a.needs_review) then raise exception 'Сначала оцените ответы, ожидающие проверки'; end if;
 result:=public.control_quiz_game_legacy(p_code,p_host_secret,p_action,null,p_question_id,p_scoring_mode);
 if p_action='reveal' and r.admin_document->>'score_timing'='round' then
  select not exists(select 1 from public.questions where room_id=r.id and question_number=q.question_number+1 and definition->>'round_number'=q.definition->>'round_number') into end_round;
  if end_round then update public.players p set score=coalesce((select sum(a.points_awarded) from public.answers a where a.player_id=p.id),0) where p.room_id=r.id; end if;
 end if;
 return public.quiz_game_snapshot(r.id,null);
end $$;

create or replace function public.submit_quiz_response(p_player_id uuid,p_player_secret uuid,p_question_id uuid,p_response jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare p public.players%rowtype;r public.rooms%rowtype;q public.questions%rowtype;d jsonb;v jsonb;score numeric:=0;hits integer;misses integer;k text;review boolean:=false;selection integer:=0;
begin
 select * into p from public.players where id=p_player_id and player_token=p_player_secret;
 if not found then raise exception 'Нет доступа игрока' using errcode='42501'; end if;
 select * into strict r from public.rooms where id=p.room_id for update;
 if exists(select 1 from public.answers where question_id=p_question_id and player_id=p.id) then return jsonb_build_object('accepted',true); end if;
 select * into q from public.questions where id=p_question_id and room_id=r.id and question_number=r.current_question;
 if not found or r.status<>'playing' or r.game_phase<>'question' or clock_timestamp()>=r.question_started_at+make_interval(secs=>q.duration) then raise exception 'Вопрос закрыт или время вышло'; end if;
 d:=q.definition;k:=d->>'kind';
 if k in ('single','multiple') then
  if jsonb_typeof(p_response->'choices') is distinct from 'array' then raise exception 'Выберите вариант'; end if;
  if jsonb_array_length(p_response->'choices') not between 1 and 8 or (k='single' and jsonb_array_length(p_response->'choices')<>1) then raise exception 'Неверное число вариантов'; end if;
  if (select count(distinct value) from jsonb_array_elements(p_response->'choices'))<>jsonb_array_length(p_response->'choices') then raise exception 'Варианты повторяются'; end if;
  for v in select value from jsonb_array_elements(p_response->'choices') loop
   if v::text !~ '^[0-7]$' then raise exception 'Неверный вариант'; end if;
   if v::text::integer>=jsonb_array_length(d->'options') then raise exception 'Неверный вариант'; end if;
  end loop;
  select count(*) filter(where d->'answer_key' @> jsonb_build_array(value)),count(*) filter(where not(d->'answer_key' @> jsonb_build_array(value))) into hits,misses from jsonb_array_elements(p_response->'choices');
  if coalesce((d->>'partial')::boolean,false) and k='multiple' then score:=q.points*greatest(0,hits-misses)/jsonb_array_length(d->'answer_key');
  elsif misses=0 and hits=jsonb_array_length(d->'answer_key') then score:=q.points; end if;
  selection:=least((p_response->'choices'->>0)::integer,3);
 elsif k in ('text','manual') then
  if jsonb_typeof(p_response->'text') is distinct from 'string' or length(btrim(p_response->>'text')) not between 1 and 500 then raise exception 'Ответ: от 1 до 500 символов'; end if;
  review:=k='manual';
  if k='text' and exists(select 1 from jsonb_array_elements_text(d->'accepted') a where public.quiz_normalize_answer(a,coalesce((d->>'case_sensitive')::boolean,false))=public.quiz_normalize_answer(p_response->>'text',coalesce((d->>'case_sensitive')::boolean,false))) then score:=q.points; end if;
 else raise exception 'Используйте ответ на обычный вопрос'; end if;
 insert into public.answers(question_id,player_id,selected_option,points_awarded,response,needs_review) values(q.id,p.id,selection,round(score,2),p_response,review);
 return jsonb_build_object('accepted',true);
end $$;
create or replace function public.submit_quiz_answer(p_player_id uuid,p_player_secret uuid,p_question_id uuid,p_option integer) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from public.questions where id=p_question_id and definition<>'{}') then return public.submit_quiz_response(p_player_id,p_player_secret,p_question_id,jsonb_build_object('choices',jsonb_build_array(p_option))); end if;
 return public.submit_quiz_answer_legacy(p_player_id,p_player_secret,p_question_id,p_option);
end $$;
create or replace function public.grade_quiz_response(p_code text,p_host_secret uuid,p_answer_id uuid,p_points numeric) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.rooms%rowtype;q public.questions%rowtype;a public.answers%rowtype;
begin
 select * into r from public.rooms where code=p_code and host_token=p_host_secret for update;
 if not found then raise exception 'Нет доступа ведущего' using errcode='42501'; end if;
 if r.status<>'playing' then raise exception 'Оценивание доступно во время игры'; end if;
 select qu.* into q from public.questions qu join public.answers ans on ans.question_id=qu.id where ans.id=p_answer_id and qu.room_id=r.id;
 select * into a from public.answers where id=p_answer_id and needs_review;
 if q.id is null or a.id is null then raise exception 'Ответ уже оценён или недоступен'; end if;
 if p_points is null or p_points<0 or p_points>q.points or p_points<>round(p_points,2) then raise exception 'Укажите баллы от 0 до стоимости вопроса, с точностью до сотых'; end if;
 update public.answers set points_awarded=p_points,needs_review=false where id=p_answer_id;
 if r.game_phase='reveal' and (r.scoring_mode='reveal' or (r.admin_document->>'score_timing'='round' and not exists(select 1 from public.questions where room_id=r.id and question_number=r.current_question+1 and definition->>'round_number'=q.definition->>'round_number'))) then
  update public.players pl set score=coalesce((select sum(ans.points_awarded) from public.answers ans where ans.player_id=pl.id),0) where pl.room_id=r.id;
 end if;
 return public.quiz_game_snapshot(r.id,null);
end $$;

-- Only administrators can upload. Media are served publicly for games; filenames are random.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('quiz-media','quiz-media',true,20971520,array['image/jpeg','image/png','image/webp','image/gif','audio/mpeg','audio/ogg','video/mp4','video/webm']) on conflict(id) do nothing;
drop policy if exists quiz_admin_media_insert on storage.objects;
create policy quiz_admin_media_insert on storage.objects for insert to authenticated with check(bucket_id='quiz-media' and public.is_quiz_admin());
drop policy if exists quiz_admin_media_select on storage.objects;
create policy quiz_admin_media_select on storage.objects for select to authenticated using(bucket_id='quiz-media' and public.is_quiz_admin());

