:"single","options":["Радиотелескоп","Компас","Синематограф","Печатную машинку"],"correct":[2],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какой прибор позволяет видеть очень маленькие объекты?","kind":"single","options":["Перископ","Барометр","Спидометр","Микроскоп"],"correct":[3],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какой прибор помогает определять стороны света?","kind":"single","options":["Компас","Секундомер","Микрофон","Манометр"],"correct":[0],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Как называется устройство для записи и воспроизведения звука, созданное Эдисоном в 1877 году?","kind":"single","options":["Телеграф","Фонограф","Сейсмограф","Осциллограф"],"correct":[1],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какой учёный проводил опыты с горохом, ставшие основой генетики?","kind":"single","options":["Николай Коперник","Андре Ампер","Грегор Мендель","Эрнест Резерфорд"],"correct":[2],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какое открытие Вильгельма Рентгена используется для получения изображений костей?","kind":"single","options":["Радиоволны AM","Ультразвук","Инфракрасное излучение","Рентгеновские лучи"],"correct":[3],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какой учёный предложил гелиоцентрическую модель, изложенную в труде 1543 года?","kind":"single","options":["Николай Коперник","Аристотель","Клавдий Птолемей","Гиппократ"],"correct":[0],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Что делает холодильник с продуктами?","kind":"single","options":["Преобразует их в электричество","Поддерживает пониженную температуру","Увеличивает их массу","Удаляет из них все атомы"],"correct":[1],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false},{"text":"Какой транспорт использует колёса и педали для движения за счёт силы человека?","kind":"single","options":["Самолёт","Тепловоз","Велосипед","Лифт"],"correct":[2],"points":1,"duration":30,"explanation":"","partial":false,"case_sensitive":false}]}]}$doc$::jsonb,1) on conflict(template_key) do nothing;
